560	/// Find clashes and normalize names
561	/// 1. If column name has no clashes make all its occurrences short: 'table.column' -> 'column', 'table_alias.column' -> 'column'.
562	/// 2. If column name can't be short cause of alias with same name generate and use unique name for it.
563	/// 3. If column clashes with another column generate and use unique names for them.
564	/// 4. If column clashes with another column and it's short - it's 'ambiguous column' error.
565	/// 5. If column clashes with alias add short column name to select list. It would be removed later if not needed.
566	std::vector<TableNeededColumns> normalizeColumnNamesExtractNeeded(
567	    const std::vector<TableWithColumnNamesAndTypes> & tables,
568	    const Aliases & aliases,
569	    const std::vector<ASTIdentifier *> & identifiers,
570	    const std::unordered_set<ASTIdentifier *> & public_identifiers,
571	    UniqueShortNames & unique_names)
572	{
573	    std::vector<TableNeededColumns> needed_columns;
574	    needed_columns.reserve(tables.size());
575	    for (const auto & table : tables)
576	        needed_columns.push_back(TableNeededColumns{table.table});
577	
578	    NameSet restored_names;
579	    for (ASTIdentifier * ident : identifiers)
580	    {
581	        bool got_alias = aliases.contains(ident->name());
582	        bool allow_ambiguous = got_alias; /// allow ambiguous column overridden by an alias
583	
584	        if (auto table_pos = IdentifierSemantic::chooseTableColumnMatch(*ident, tables, allow_ambiguous))
585	        {
586	            if (!ident->isShort())
587	            {
588	                if (got_alias)
589	                {
590	                    auto alias = aliases.find(ident->name())->second;
591	                    auto alias_ident = alias->clone();
592	                    if (auto * alias_ident_typed = alias_ident->as<ASTIdentifier>())
593	                    {
594	                        alias_ident_typed->restoreTable();
595	                        bool alias_equals_column_name = alias_ident->getColumnNameWithoutAlias() == ident->getColumnNameWithoutAlias();
596	                        if (!alias_equals_column_name)
597	                            throw Exception(ErrorCodes::AMBIGUOUS_COLUMN_NAME, "Alias clashes with qualified column '{}'", ident->name());
598	                    }
599	                }
600	                String short_name = ident->shortName();
601	                String original_long_name;
602	                if (public_identifiers.contains(ident))
603	                    original_long_name = ident->name();
604	
605	                size_t count = countTablesWithColumn(tables, short_name);
606	                const auto & table = tables[*table_pos];
607	
608	                /// isValidIdentifierBegin retuired to be consistent with TableJoin::deduplicateAndQualifyColumnNames
609	                if (count > 1 || aliases.contains(short_name) || !isValidIdentifierBegin(short_name.at(0)))
610	                {
611	                    IdentifierSemantic::setColumnLongName(*ident, table.table); /// table.column -> table_alias.column
612	                    const auto & unique_long_name = ident->name();
613	
614	                    /// For tables moved into subselects we need unique short names for clashed names
615	                    String unique_short_name = unique_names.longToShort(unique_long_name);
616	                    ident->setShortName(unique_short_name);
617	                    needed_columns[*table_pos].column_clashes.emplace(short_name, unique_short_name);
618	                }
619	                else
620	                {
621	                    if (!table.hasColumn(short_name))
622	                    {
623	                        throw Exception(ErrorCodes::UNKNOWN_IDENTIFIER,
624	                                        "There's no column '{}' in table '{}'",
625	                                        ident->name(),
626	                                        table.table.getQualifiedNamePrefix(false));
627	                    }
628	                    ident->setShortName(short_name); /// table.column -> column
629	                    needed_columns[*table_pos].no_clashes.emplace(short_name);
630	                }
631	
632	                restoreName(*ident, original_long_name, restored_names);
633	            }
634	            else if (got_alias)
635	            {
636	                String short_name = ident->shortName();
637	                if (!isValidIdentifierBegin(short_name.at(0)))
638	                {
639	                    String original_long_name;
640	                    if (public_identifiers.contains(ident))
641	                        original_long_name = ident->name();
642	
643	                    const auto & table = tables[*table_pos];
644	                    IdentifierSemantic::setColumnLongName(*ident, table.table); /// table.column -> table_alias.column
645	                    const auto & unique_long_name = ident->name();
646	
647	                    String unique_short_name = unique_names.longToShort(unique_long_name);
648	                    ident->setShortName(unique_short_name);
649	                    needed_columns[*table_pos].column_clashes.emplace(short_name, unique_short_name);
650	                    restoreName(*ident, original_long_name, restored_names);
651	                }
652	                else
653	                    needed_columns[*table_pos].alias_clashes.emplace(ident->shortName());
654	            }
655	            else
656	            {
657	                String short_name = ident->shortName();
658	                if (!isValidIdentifierBegin(short_name.at(0)))
659	                {
660	                    String original_long_name;
661	                    if (public_identifiers.contains(ident))
662	                        original_long_name = ident->name();
663	
664	                    const auto & table = tables[*table_pos];
665	                    IdentifierSemantic::setColumnLongName(*ident, table.table); /// table.column -> table_alias.column
666	                    const auto & unique_long_name = ident->name();
667	
668	                    String unique_short_name = unique_names.longToShort(unique_long_name);
669	                    ident->setShortName(unique_short_name);
670	                    needed_columns[*table_pos].column_clashes.emplace(short_name, unique_short_name);
671	                    restoreName(*ident, original_long_name, restored_names);
672	                }
673	                else
674	                    needed_columns[*table_pos].no_clashes.emplace(ident->shortName());
675	            }
676	        }
677	    }
678	
679	    return needed_columns;
680	}
