682	/// Make expression list for current subselect
683	boost::intrusive_ptr<ASTExpressionList> subqueryExpressionList(
684	    size_t table_pos,
685	    const std::vector<TableNeededColumns> & needed_columns,
686	    const std::vector<std::vector<ASTPtr>> & alias_pushdown)
687	{
688	    auto expression_list = make_intrusive<ASTExpressionList>();
689	
690	    /// First time extract needed left table columns manually.
691	    /// Next times extract left table columns via QualifiedAsterisk: `--s`.*
692	    if (table_pos == 1)
693	        needed_columns[0].fillExpressionList(*expression_list);
694	    else
695	        expression_list->children.emplace_back(makeSubqueryQualifiedAsterisk());
696	
697	    /// Add needed right table columns
698	    needed_columns[table_pos].fillExpressionList(*expression_list);
699	
700	    for (const auto & expr : alias_pushdown[table_pos])
701	        expression_list->children.emplace_back(expr);
702	
703	    return expression_list;
704	}
705	
