355	void renameDuplicatedColumns(const ASTSelectQuery * select_query)
356	{
357	    ASTs & elements = select_query->select()->children;
358	
359	    std::set<String> all_column_names;
360	    std::set<String> assigned_column_names;
361	
362	    for (auto & expr : elements)
363	        all_column_names.insert(expr->getAliasOrColumnName());
364	
365	    for (auto & expr : elements)
366	    {
367	        auto name = expr->getAliasOrColumnName();
368	        if (!assigned_column_names.insert(name).second)
369	        {
370	            /// We can't rename with aliases if it doesn't support alias (e.g. asterisk)
371	            if (!dynamic_cast<ASTWithAlias *>(expr.get()))
372	                continue;
373	
374	            size_t i = 1;
375	            while (all_column_names.contains(name + "_" + toString(i)))
376	                ++i;
377	
378	            name = name + "_" + toString(i);
379	            expr = expr->clone();   /// Cancels fuse of the same expressions in the tree.
380	            expr->setAlias(name);
381	
382	            all_column_names.insert(name);
383	            assigned_column_names.insert(name);
384	        }
385	    }
386	}
