388	/// Sometimes we have to calculate more columns in SELECT clause than will be returned from query.
389	/// This is the case when we have DISTINCT or arrayJoin: we require more columns in SELECT even if we need less columns in result.
390	/// Also we have to remove duplicates in case of GLOBAL subqueries. Their results are placed into tables so duplicates are impossible.
391	/// Also remove all INTERPOLATE columns which are not in SELECT anymore.
392	void removeUnneededColumnsFromSelectClause(ASTSelectQuery * select_query, const Names & required_result_columns, bool remove_dups)
393	{
394	    ASTs & elements = select_query->select()->children;
395	
396	    std::map<String, size_t> required_columns_with_duplicate_count;
397	
398	    if (!required_result_columns.empty())
399	    {
400	        /// Some columns may be queried multiple times, like SELECT x, y, y FROM table.
401	        for (const auto & name : required_result_columns)
402	        {
403	            if (remove_dups)
404	                required_columns_with_duplicate_count[name] = 1;
405	            else
406	                ++required_columns_with_duplicate_count[name];
407	        }
408	    }
409	    else if (remove_dups)
410	    {
411	        /// Even if we have no requirements there could be duplicates cause of asterisks. SELECT *, t.*
412	        for (const auto & elem : elements)
413	            required_columns_with_duplicate_count.emplace(elem->getAliasOrColumnName(), 1);
414	    }
415	    else
416	        return;
417	
418	    NameSet required_by_interpolate;
419	
420	    if (select_query->interpolate())
421	    {
422	        auto & children = select_query->interpolate()->children;
423	        if (!children.empty())
424	        {
425	            NameToNameSetMap expressions;
426	
427	            auto interpolate_visitor = [](const ASTPtr ast, NameSet & columns) -> void
428	            {
429	                auto interpolate_visitor_impl = [](const ASTPtr node, NameSet & cols, auto self) -> void
430	                {
431	                    if (const auto * ident = node->as<ASTIdentifier>())
432	                        cols.insert(ident->name());
433	                    else if (const auto * func = node->as<ASTFunction>())
434	                        for (const auto & elem : func->arguments->children)
435	                            self(elem, cols, self);
436	                };
437	                interpolate_visitor_impl(ast, columns, interpolate_visitor_impl);
438	            };
439	
440	            for (const auto & elem : children)
441	            {
442	                if (auto * interpolate = elem->as<ASTInterpolateElement>())
443	                {
444	                    NameSet needed_columns;
445	                    interpolate_visitor(interpolate->expr, needed_columns);
446	                    expressions.emplace(interpolate->column, std::move(needed_columns));
447	                }
448	            }
449	
450	            for (const auto & name : required_result_columns)
451	                if (const auto it = expressions.find(name); it != expressions.end())
452	                    required_by_interpolate.insert(it->second.begin(), it->second.end());
453	        }
454	    }

