193	void QueryNormalizer::visit(ASTSelectQuery & select, const ASTPtr &, Data & data)
194	{
195	    for (auto & child : select.children)
196	    {
197	        if (needVisitChild(child))
198	            visit(child, data);
199	    }
200	
201	    /// If the WHERE clause or HAVING consists of a single alias, the reference must be replaced not only in children,
202	    /// but also in where_expression and having_expression.
203	    if (select.prewhere())
204	        visit(select.refPrewhere(), data);
205	    if (select.where())
206	        visit(select.refWhere(), data);
207	    if (select.having())
208	        visit(select.refHaving(), data);
209	}
