211	/// Don't go into subqueries.
212	/// Don't go into select query. It processes children itself.
213	/// Do not go to the left argument of lambda expressions, so as not to replace the formal parameters
214	///  on aliases in expressions of the form 123 AS x, arrayMap(x -> 1, [2]).
215	void QueryNormalizer::visitChildren(IAST * node, Data & data)
216	{
217	    if (auto * func_node = node->as<ASTFunction>())
218	    {
219	        if (func_node->tryGetQueryArgument())
220	        {
221	            if (func_node->name != "view")
222	                throw Exception(ErrorCodes::BAD_ARGUMENTS, "Query argument can only be used in the `view` TableFunction");
223	            /// Don't go into query argument.
224	            return;
225	        }
226	
227	        /// For lambda functions we need to avoid replacing lambda parameters with external aliases, for example,
228	        /// Select 1 as x, arrayMap(x -> x + 2, [1, 2, 3])
229	        /// shouldn't be replaced with Select 1 as x, arrayMap(x -> **(1 as x)** + 2, [1, 2, 3])
230	        Aliases extracted_aliases;
231	        if (func_node->name == "lambda")
232	        {
233	            Names lambda_aliases = RequiredSourceColumnsMatcher::extractNamesFromLambda(*func_node);
234	            for (const auto & name : lambda_aliases)
235	            {
236	                auto it = data.aliases.find(name);
237	                if (it != data.aliases.end())
238	                {
239	                    extracted_aliases.insert(data.aliases.extract(it));
240	                }
241	            }
242	        }
243	
244	        /// We skip the first argument. We also assume that the lambda function can not have parameters.
245	        size_t first_pos = 0;
246	        if (func_node->name == "lambda")
247	            first_pos = 1;
248	
249	        if (func_node->arguments)
250	        {
251	            auto & func_children = func_node->arguments->children;
252	
253	            for (size_t i = first_pos; i < func_children.size(); ++i)
254	            {
255	                auto & child = func_children[i];
256	
257	                if (needVisitChild(child))
258	                    visit(child, data);
259	            }
260	        }
261	
262	        if (func_node->window_definition)
263	        {
264	            visitChildren(func_node->window_definition.get(), data);
265	        }
266	
267	        for (auto & it : extracted_aliases)
268	        {
269	            data.aliases.insert(it);
270	        }
271	    }
272	    else if (!node->as<ASTSelectQuery>())
273	    {
274	        for (auto & child : node->children)
275	            if (needVisitChild(child))
276	                visit(child, data);
277	    }
